+/**
+ * Variance per item between two days (inclusive): theoretical use from sales
+ * sold in those days, actual use from every consume movement, and the
+ * difference (actual - theoretical). Only items where either is above zero.
+ */
+export function varianceReport(store, from, to) {
+  const r3 = (n) => Math.round(n * 1000) / 1000;
+  const lines = new Map();
+  const line = (itemId) => {
+    if (!lines.has(itemId)) lines.set(itemId, { itemId, theoretical: 0, actual: 0 });
+    return lines.get(itemId);
+  };
+  for (const s of store.data.sales ?? []) {
+    const day = s.soldAt.slice(0, 10);
+    if (day < from || day > to) continue;
+    for (const u of s.uses) line(u.itemId).theoretical += u.qty;
+  }
+  for (const m of store.data.movements) {
+    if (m.type !== "consume") continue;
+    const day = m.at.slice(0, 10);
+    if (day < from || day > to) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (batch) line(batch.itemId).actual += m.qty;
+  }
+  return [...lines.values()]
+    .map((l) => ({ itemId: l.itemId, theoretical: r3(l.theoretical), actual: r3(l.actual), difference: r3(l.actual - l.theoretical) }))
+    .filter((l) => l.theoretical > 0 || l.actual > 0)
+    .sort((a, b) => a.itemId - b.itemId);
+}
